def find_root_vertex(n, edges):
    # Create adjacency list representation of the tree
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u-1].append(v-1)
        adj[v-1].append(u-1)

    def dfs(vertex, parent, depth):
        for neighbor in adj[vertex]:
            if neighbor == parent:
                continue
            if dfs(neighbor, vertex, depth+1):
                return True
        return False

    for vertex in range(n):
        if dfs(vertex, None, 1):
            return vertex + 1
    return -1

