from collections import defaultdict

def solve_night_mares(n, m, k, ranks, orders):
    # Create a list of ranks for each military man
    rank_list = [0] * (n + 1)  # Rank 0 means the man doesn't have a rank

    # Create an adjacency list for previous orders
    previous_orders = defaultdict(list)
    for i, j in orders:
        previous_orders[j].append(i)

    # Process the current assignments
    for i, rank in enumerate(ranks):
        rank_list[i+1] = rank  # Assign the current rank to the current order

    # Try to assign the next highest rank
    for rank in range(k + 1):
        can_assign = True
        node = n  # Start from the highest rank possible
        while node >= 1 and can_assign:
            if node in previous_orders:
                for neighbor in previous_orders[node]:
                    prev_rank = rank_list[neighbor]
                    if prev_rank < rank:  # Rank of neighbors cannot be higher than own rank
                        can_assign = False
            if can_assign:
                if rank == k:
                    rank_list[node] = rank + 1  # If at k, it automatically gets the next
                else:
                    rank_list[node] = rank + 1  # Add 1 to current rank to get to next rank
            if not can_assign:
                node -= 1  # backtrack
            can_assign = True
            for neighbor in previous_orders[node]:
                prev_rank = rank_list[neighbor]
                if prev_rank < rank:
                    can_assign = False
            if node < 1:
                break

    # Check if the rank_list contains all the ranks from 1 to k inclusive
    all_ranks_found = all(rank_list[i] >= 1 for i in range(1, n + 1))

    # If a solution is found, create the output, otherwise return -1
    if all_ranks_found:
        return rank_list[1:]
    else:
        return [-1]

