        dy = ranks[y] - 2
        for x in range(1, k + 1):
            if x + dy > k:
                continue
            if y in relationships and relationships[y][x] in detected_claims:
                continue
            heappush(ranks, x + dy)
            heappush(detected_claims, relationships[y][x])
            if len(heappop(max_heap)) < x + dy:
