from collections import deque

def create_number(n, digits):
    return int(''.join(map(str, digits)))

def find_min_swaps_to_win(n, a, b):
    a, b = list(str(a)), list(str(b))
    if len(a) != len(b) or a > b:
        return -1

    queue = deque()
    queue.append((create_number(n, a), a.copy(), 0))

    while queue:
        current_number, digits, moves = queue.popleft()
        if current_number == create_number(n, b):
            return moves
        if len(digits) < n:
            for i in range(n-1):
                if i == 0 and digits[i] == '9':
                    continue
                digits_copy = digits[:]
                if i == n-2:
                    digits_copy[i-1] = '0'
                    digits_copy[i+1] = str(int(digits[i+1]) + 1)
                else:
                    digits_copy[i+1] = str(int(digits[i+1]) + 1)
                    digits_copy[i] = str(int(digits[i]) + 1)
                queue.append((create_number(n, digits_copy), digits_copy.copy(), moves + 1))

    return -1

