def calculate_max_distance(points: List[tuple]) -> int:
    max_distance_squared = 0
    for i in range(1, len(points)):
        distance1 = (points[i][0] - points[0][0]) ** 2 + (points[i][1] - points[0][1]) ** 2
        for j in range(1, i):
            distance2 = (points[i][j][0] - points[j][0]) ** 2 + (points[i][j][1] - points[j][1]) ** 2
            if distance1 > distance2:
                distance1 = distance2
        if distance1 > max_distance_squared:
            max_distance_squared = distance1
    return max_distance_squared

def solve(n: int, points: List[tuple]) -> None:
    points = [shuffle_point(point) for point in points]
    print(calc_max_distance(points[:n]))

def shuffle_point(point: tuple) -> tuple:
    return random.sample([point[0], point[1]], 2)

def calc_max_distance(points: List[tuple]) -> int:
    import numpy as np
    points = np.array(points)
    points = points.reshape(-1, 1, 2)
    max_distance_squared = 0
    for i in range(len(points)):
        distances = np.linalg.norm(points - points[i], axis=1)
        max_distance_squared = max(max_distance_squared, max(distances))
    return max_distance_squared

def read_input() -> tuple:
    n = int(input().strip())
    points = []
    for _ in range(n):
        x, y = map(int, input().strip().split())
        points.append((x, y))
    return n, points

def write_output(n: int, points: List[tuple]):
    solve(n, points)

def main():
    n, points = read_input()
    write_output(n, points)

if __name__ == "__main__":
    main()
