                    dp[i][j] *= dp[i][k - 1] // (k - 1)
                    dp[i][j] %= MOD
                if k < j:
                    dp[i][j] *= dp[k][j - 1] * (j - k) % MOD
                    dp[i][j] %= MOD
            dp[i][k] += k
            dp[i][k] %= MOD
    return dp[n][n]

def rarity(n):
    dp = [[1] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(2, i + 1):
            dp[i][j] = dp[i - 1][j] * 2 % MOD
            dp[i][j] = dp[i - 1][j - 1] * j % MOD
        dp[i][i] += (i ** 2) % MOD
        dp[i][i] %= MOD
    return dp[n][n]

