from typing import List
from math import gcd

def find_permutation_and_map(pieces: List[List[int]]) -> (List[int], List[int]):
    n = len(pieces)

    def preprocess():
        modulus = n - 2
        offsets = []

        for i in range(n):
            rev_offset = (n - 1 - i) % modulus
            while rev_offset == 0:
                rev_offset += modulus
            offset = i % modulus
            if offset < 0:
                offset += modulus
            offsets.append((offset, rev_offset))

        for i in range(n - 1, 0, -1):
            if i == n - 1:
                yield []
            else:
                offset0, rev_offset0 = offsets[i - 2]
                offset1, rev_offset1 = offsets[i - 1]
                if offset0 <= offset1:
                    yield offset0 * modulus + offset1
                else:
                    yield offset1 * modulus + offset0

    mapping = dict()
    used = [False] * n
    for offset in preprocess():
        for i in range(len(offset)):
            if offset[i] in mapping and mapping[offset[i]] not in used:
                return mapping, used, mapping[offset[i]], used[offset[i]]
        for i in range(len(offset)):
            if used[offset[i]]:
                mapping[offset[i]] = i
            else:
                used[offset[i]] = True
        used[offset[-1]] = True

    raise ValueError("No solution found")

def solve(inputs: List[str]):
