from math import isqrt

def prime_factors(n, prime_set):
    factors = 0
    while n % 2 == 0:
        n //= 2
        factors += 1
    for prime in prime_set:
        if prime * prime > n:
            break
        while n % prime == 0:
            factors += 1
            n //= prime
    if n > 1:
        factors += 1
    return factors

def find_kth_number(n, prime_set, k):
    prime_set.sort()
    indices = sorted(range(len(prime_set)), key=lambda i: prime_set[i])
    current_k = 1
    target_k = n * (k - 1)
    for i in range(len(prime_set) - 1, 0, -1):
        count = reduce(lambda a, b: a * b, (n // (p ** current_k) for p in prime_set[i:]))
        if indices[i] == i:
            single_prime_count = prime_factors(n // (prime_set[indices[i]] ** count), prime_set)
            if single_prime_count == 1:
                if target_k - current_k == source:
                    continue
                target_k -= single_prime_count
                continue
            else:
