import collections

def bfs(start, graph, visited, degrees):
    queue = collections.deque([start])
    visited[start] = True
    connected = collections.defaultdict(list)
    while queue:
        current = queue.popleft()
        for neighbor in graph[current]:
            if not visited[neighbor]:
                queue.append(neighbor)
                visited[neighbor] = True
                degrees[neighbor] = degrees[current] + 1
                connected[neighbor].append(current)

    if len(degrees) == len(graph):
        return start
    return -1

def findRoot(n):
    graph = [[] for _ in range(n)]
    for i in range(1, n-1):
        a, b = map(int, input().split())
        graph[a-1].append(b-1)
        graph[b-1].append(a-1)

    degrees = [0] * (n-1)*2
    visited = [False] * n
    for i in range(n-1):
        start = i
        if bfs(start, graph, visited, degrees) == -1:
            return -1
    return visited.index(False) + 1

