from collections import defaultdict

def query(arr, l, r, k):
    if k == 2:
        return bisect_right(arr, r) - bisect_left(arr, l)
    elif k == 3:
        return bisect_right(arr, r) - bisect_left(arr, l) - 1
    elif k == 4:
        l_index = bisect_left(arr, l)
        r_index = bisect_right(arr, r)
        return (r_index - l_index) - 1

def solve():
    n, q = map(int, input().split())
    a = list(map(lambda x: ord(x) - ord('a'), input().strip()))
    sorted_indices = sorted(range(len(a)), key=lambda i: a[i])

