    for index, value in enumerate(a):
        indices_map[value].append(index)

    for _ in range(q):
        l, r, k = map(int, input().split())
        indices = indices_map[k]
        if k in [1, 4]:
            answer = query(sorted_indices, indices[lower_bound(sorted_indices, r) - 1], indices[bisect_right(sorted_indices, r)], k)
            if lower_bound(indices_map, k) == k:
                answer = -1
        else:
