import sys

def find_min_cost_operations(P):
    n = len(P)
    operations = []
    operations_cost = []

    for i in range(n):
        if not operations or (operations[-1] < 0 and operations[-1][1] <= i + 1):
            operations.append((i, i))
            operations_cost.append(0)
        else:
            for j in range(len(operations)):
                if i > operations[j][1]:
                    if (operations[j][0] > i or (operations[j][0] == i and operations[j][1] <= i + 1)):
                        operations.append((operations[j][0], i))
                        operations_cost.append(-abs(operations[j][1] - operations[j][0]))
                        break

    psum = [0] * (n + 1)

    for i in range(1, n + 1):
        for j in range(-1, operations_cost[i-1] + 2):
            if j != -1:
                psum[i] += (j % i * operations_cost[i-1] + operations[j % i][1] * (i - (j % i)) + (operations_cost[i-1] - operations[j % i]) * abs(operations[j % i][1] - operations[j % i-1][1]) + abs(operations[j % i][1] - operations[j % i-1][1]))
            else:
                psum[i] += (j % i * operations_cost[i-1] + operations[j % i][1] * (i - (j % i)) + (operations_cost[i-1] - operations[j % i]) * abs(operations[j % i][1] - operations[j % i-1][1]))

    return psum[-1] // 2, psum[-1] % 2

