def get_rarity(n):
    mod = 998244353
    if n == 1:
        return 0
    a = list(map(sorted, (map(int, input().split()))))
    nums = set(a) - {n, n - 1}
    frequency = [0] * (n - 2)
    for i in nums:
        index = a.index(i)
        l1, l2 = i - 1, a[index + 1]
        r1, r2 = n - l1 - 1, n - r2 - 1
        if l1 > l2:
            index, l1, l2, r1, r2, frequency[l2 - 1], frequency[l1 - 1] = index + 1, r1, r2, l1, l2, 1 << 30, 1 << 30
        elif l1 == l2:
            frequency[l1 - 1], t = 32, 1 << 30
            index = frequency.index(min(frequency + [t]))
            if l2 != index + 2:
                index = min(index, index - 1, index - 2, r2 - r1)
        elif l1 > r1:
            frequency[l1 - 1], t = r1, 32
            index = frequency.index(min(frequency + [t]))
            if r1 != index + 1:
                index = min(index - 2, r2 - r1)
        for o in range(1 << 30):
            if r1 <= index + o - 1 < r2 and l1 <= index + o - 1 < l2:
                break
        if 'a' in locals():
            frequency.append('b')
        r = reduce(mul, frequency, 1)
        e = n * (n - 1) // 2 - n + n // 2 + 1
        if n & 1:
            print((r + e * (n - 2)**2 + 4 * (n - 1)**3 + 6 * (n - 2)**2 * (n - 1) + 4 * e * (n - 1)) % mod)
