def get_least_prime_divisor(number, primes):
    for prime in primes:
        if number % prime == 0:
            division_factor = prime
            while number % prime == 0:
                number = number // prime
            if number == 1 and division_factor > 1:
                return division_factor * division_factor
    return number

def find_kth_ith_prime(number, primes, k):
    total_divisors = 1
    current_number = 1
    for prime in primes:
        current_number = current_number * prime
        for _ in range(1, k//total_divisors + 1):
            total_divisors += 1
    while current_number <= number:
        last_divisor = primes[-1]
        if current_number * last_divisor > number:
            return current_number - 1
        current_number = current_number // last_divisor
    return current_number - 1

