from heapq import heappush, heappop

def find_kth_integer(primes, k):
    primes.sort()
    n = len(primes)
    dp = [1] * n
    for i in range(2, n):
        if primes[i] == primes[i-1]:
            dp[i] = dp[i-1]
            continue
        j = i - 1
        while j >= 0 and primes[j] / primes[i] > i:
            j -= 1
        j += 1
        dp[i] = min(dp[i // primes[j]] + 1, dp[j] + i // primes[i])
    if dp[n-1] >= k:
        return k
    else:
        return k + dp[n-1]
